BEGIN TRANSACTION;
CREATE TABLE admin_sessions (token TEXT PRIMARY KEY, owner TEXT NOT NULL, version TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE catalogs (owner TEXT PRIMARY KEY, data TEXT NOT NULL, revision INTEGER NOT NULL);
CREATE TABLE orders (id TEXT PRIMARY KEY, owner TEXT NOT NULL, branch TEXT NOT NULL, day TEXT NOT NULL, items TEXT NOT NULL, created INTEGER NOT NULL, done INTEGER NOT NULL DEFAULT 0, delivery_days INTEGER, delivery_day TEXT, held TEXT, item_eta TEXT);
CREATE TABLE role_passwords (role TEXT PRIMARY KEY, salt TEXT NOT NULL, digest TEXT NOT NULL);
COMMIT;
